package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class MigrationMappingsAcceptance {
 static final String ROOT="/api/openservice/migration-mappings";
 static Map<String,Object> field(int id,String table,String name,String type){return map("sys_id",MigrationSource.key(id),"name",table,"element",name,"internal_type",type,"column_label",name,"mandatory","false","max_length","160","reference","");}
 static void seed(){MigrationSource.reset();MigrationSource.tables.put("sys_db_object",List.of(map("sys_id",MigrationSource.key(1),"name","incident","super_class",MigrationSource.key(2)),map("sys_id",MigrationSource.key(2),"name","task","super_class","")));MigrationSource.tables.put("sys_dictionary",List.of(field(10,"task","short_description","string"),field(11,"incident","state","integer"),field(12,"task","priority","integer"),field(13,"incident","custom_details","string")));MigrationSource.tables.put("incident",List.of(map("sys_id",MigrationSource.key(1000),"short_description","Migrated mapped incident","state","1","priority","3","custom_details","Retained renamed description")));}
 static Map<String,Object> assess(){return map("source",MigrationSource.origin(),"source_table","incident","target","incident","token",MigrationSource.TOKEN);}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r,int code)throws Exception{return TransferAcceptance.result(r,code);}

 static String create(WorkflowSupport h)throws Exception{return result(h.json("POST",ROOT,assess(),auth("admin")),201).get("assessment_id").toString();}
 static Map<String,Object> page(WorkflowSupport h,String id)throws Exception{return result(h.get(ROOT+"/"+id,auth("admin")),200);}
 static Map<String,Object> mapping(){return map("fields",map("short_description","short_description","state","state","priority","priority","description","custom_details"),"values",map("priority",map("3","2")));}
 static Map<String,Object> review(WorkflowSupport h,String id)throws Exception{return result(h.json("POST",ROOT+"/"+id,map("operation","review","revision",page(h,id).get("revision"),"mapping",mapping()),auth("admin")),200);}
 static Map<String,Object> confirm(Object revision){return map("operation","create","revision",revision,"confirm",true);}
 static void run(WorkflowSupport h)throws Exception{
  seed();String id=create(h);var p=page(h,id);assertEquals(List.of("incident","task"),p.get("hierarchy"));assertEquals("short_description",object(p.get("suggested")).get("short_description"));assertEquals(3,MigrationSource.queries.size());assertTrue(MigrationSource.queries.get(0).contains("name=incident^ORDERBYsys_id"));assertTrue(MigrationSource.queries.get(1).contains("sys_id="+MigrationSource.key(2)));assertTrue(MigrationSource.queries.get(2).contains("nameINincident,task"));assertFalse(JSON.writeValueAsString(p).contains(MigrationSource.TOKEN));assertEquals(1,objects(result(h.get(ROOT,auth("admin")),200).get("assessments")).size());assertEquals(200,h.get("/admin/migration-mappings/"+id,auth("admin")).statusCode());
  var reviewed=review(h,id);assertEquals(true,reviewed.get("current"));assertEquals(2,reviewed.get("revision"));var request=confirm(2);var created=result(h.json("POST",ROOT+"/"+id,request,auth("admin")),200);String job=created.get("job_id").toString();assertFalse(job.isEmpty());assertEquals(job,result(h.json("POST",ROOT+"/"+id,request,auth("admin")),200).get("job_id"));assertEquals(409,h.json("POST",ROOT+"/"+id,map("operation","review","revision",2,"mapping",mapping()),auth("admin")).statusCode());new Store(h.environment);assertEquals(job,page(h,id).get("job_id"));
  var fetched=TransferAcceptance.fetch(h,job);assertEquals("review",object(fetched.get("detail")).get("status"));result(h.json("POST",TransferAcceptance.API+"/"+job+"/preview",map(),auth("admin")),200);try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_record WHERE sys_id=?",MigrationSource.key(1000)));}result(h.json("POST",TransferAcceptance.API+"/"+job+"/apply",map(),auth("admin")),200);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var record=Service.readRecord(db,"incident",MigrationSource.key(1000));assertEquals("Retained renamed description",object(record.get("data")).get("description"));assertEquals("2",object(record.get("data")).get("priority"));assertEquals("private",RecordAccess.status(db,MigrationSource.key(1000)).get("visibility"));assertFalse(JSON.writeValueAsString(db.all("SELECT definition FROM os_source_assessment")).contains(MigrationSource.TOKEN));assertFalse(JSON.writeValueAsString(db.all("SELECT detail FROM os_security_event WHERE action LIKE 'migration.mapping_%'")).contains(MigrationSource.TOKEN));assertEquals(1,db.count("SELECT COUNT(*) FROM os_transfer_job"));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  seed();h.account("MappingAgent","agent");h.account("MappingReader","reader");h.account("MappingOther","admin");assertEquals(401,h.get(ROOT,null).statusCode());for(String user:List.of("MappingAgent","MappingReader")){assertEquals(403,h.get(ROOT,auth(user)).statusCode());assertEquals(403,h.json("POST",ROOT,assess(),auth(user)).statusCode());}String id=create(h),ui="/admin/migration-mappings/"+id;assertEquals(404,h.get(ROOT+"/"+id,auth("MappingOther")).statusCode());assertEquals(404,h.json("POST",ROOT+"/"+id,confirm(1),auth("MappingOther")).statusCode());assertEquals(404,h.get(ROOT+"/"+Values.id(),auth("admin")).statusCode());assertEquals(405,h.json("PUT",ROOT,map(),auth("admin")).statusCode());assertEquals(400,h.get(ROOT+"?x=y",auth("admin")).statusCode());assertEquals(400,h.get(ROOT+"/"+id+"?x=y",auth("admin")).statusCode());assertEquals(403,h.form(ui,map("operation","create","revision","1","confirm","true"),auth("admin")).statusCode());assertEquals(400,h.protectedForm(ui,map("operation","review","revision","1","mapping","not-json"),auth("admin")).statusCode());
  for(var invalid:List.of(map(),map("source",MigrationSource.origin(),"source_table","incident","target","incident","token",MigrationSource.TOKEN,"extra",true))){assertEquals(400,h.json("POST",ROOT,invalid,auth("admin")).statusCode());}for(var change:List.of(Map.entry("source_table","incident^ORname=task"),Map.entry("source_table","sys_user"),Map.entry("target","bad/name"),Map.entry("token","bad token"),Map.entry("source","http://unapproved.invalid"))){var body=assess();body.put(change.getKey(),change.getValue());assertEquals(400,h.json("POST",ROOT,body,auth("admin")).statusCode());}
  for(var bad:List.of(map(),map("operation","wrong","revision",1),map("operation","create","revision",1,"confirm",false),map("operation","create","revision",1,"confirm",true),map("operation","create","revision","1","confirm",true),map("operation","review","revision",1,"mapping",mapping(),"extra",true)))assertEquals(400,h.json("POST",ROOT+"/"+id,bad,auth("admin")).statusCode());assertEquals(409,h.json("POST",ROOT+"/"+id,confirm(2),auth("admin")).statusCode());
  var badMaps=new ArrayList<Object>(List.of(map(),map("fields",map(),"values",map()),map("fields",map("description","custom_details"),"values",map()),map("fields",map("short_description","missing"),"values",map()),map("fields",map("short_description",1),"values",map()),map("fields",map("short_description","short_description","missing","state"),"values",map()),map("fields",map("short_description","short_description"),"values",map("state",map("1","2"))),map("fields",map("short_description","short_description"),"values",map("short_description",List.of())),map("fields",map("short_description","short_description"),"values",map("short_description",map("a",1))),map("fields",map("short_description","short_description"),"values",map("short_description",map("a".repeat(201),"b")))));var many=map("short_description","short_description");for(int n=0;n<100;n++)many.put("field_"+n,"state");badMaps.add(map("fields",many,"values",map()));many=map();for(int n=0;n<101;n++)many.put("value_"+n,"state");badMaps.add(map("fields",map("short_description","short_description"),"values",map("short_description",many)));for(var invalid:badMaps)assertEquals(400,h.json("POST",ROOT+"/"+id,map("operation","review","revision",1,"mapping",invalid),auth("admin")).statusCode());
 }
 static void metadata(WorkflowSupport h)throws Exception{
  seed();var rows=new ArrayList<Map<String,Object>>(MigrationSource.tables.get("sys_dictionary"));rows.add(field(14,"task","state","string"));rows.add(field(15,"incident","sys_password","string"));rows.add(field(16,"incident","api_token","string"));rows.add(field(17,"incident","assigned_to","reference"));rows.add(field(18,"incident","", "collection"));for(int i=19;i<115;i++)rows.add(field(i,"task","field_"+i,"string"));MigrationSource.tables.put("sys_dictionary",rows);String id=create(h);var p=page(h,id);assertEquals(4,MigrationSource.queries.size());assertEquals("incident",object(object(p.get("fields")).get("state")).get("declared_on"));for(String key:List.of("sys_password","api_token","assigned_to"))assertEquals(false,object(object(p.get("fields")).get(key)).get("eligible"));assertFalse(object(p.get("fields")).containsKey(""));
  for(String key:List.of("sys_password","api_token","assigned_to"))assertEquals(400,h.json("POST",ROOT+"/"+id,map("operation","review","revision",1,"mapping",map("fields",map("short_description",key),"values",map())),auth("admin")).statusCode());
  for(int scenario=0;scenario<13;scenario++){seed();switch(scenario){case 0->MigrationSource.tables.put("sys_db_object",List.of());case 1->MigrationSource.tables.put("sys_db_object",List.of(map("sys_id",MigrationSource.key(1),"name","incident","super_class","bad")));case 2->MigrationSource.tables.put("sys_db_object",List.of(map("sys_id",MigrationSource.key(1),"name","incident","super_class",MigrationSource.key(2)),map("sys_id",MigrationSource.key(2),"name","task","super_class",MigrationSource.key(1))));case 3->{var parents=new ArrayList<Map<String,Object>>();for(int i=1;i<=6;i++)parents.add(map("sys_id",MigrationSource.key(i),"name",i==1?"incident":"table_"+i,"super_class",i==6?"":MigrationSource.key(i+1)));MigrationSource.tables.put("sys_db_object",parents);}case 4->MigrationSource.tables.put("sys_dictionary",List.of());case 5->MigrationSource.tables.put("sys_dictionary",List.of(field(10,"task","bad/name","string")));case 6->MigrationSource.tables.put("sys_dictionary",List.of(field(10,"task","same","string"),field(11,"task","same","integer")));case 7->MigrationSource.tables.put("sys_dictionary",List.of(field(10,"task","field","t".repeat(81))));case 8->{var f=field(10,"task","field","string");f.put("column_label","x".repeat(321));MigrationSource.tables.put("sys_dictionary",List.of(f));}case 9->{var fields=new ArrayList<Map<String,Object>>();for(int i=1;i<=501;i++)fields.add(field(10+i,"task","field_"+i,"string"));MigrationSource.tables.put("sys_dictionary",fields);}case 10->MigrationSource.raw=JSON.writeValueAsString(map("result",List.of(map("sys_id",MigrationSource.key(1),"name","other","super_class",""))));case 12->{MigrationSource.dictionaryFilter=false;MigrationSource.tables.put("sys_dictionary",List.of(field(10,"foreign_table","short_description","string")));}case 11->MigrationSource.raw=JSON.writeValueAsString(map("result",List.of(map("sys_id",MigrationSource.key(1),"name","incident","super_class",MigrationSource.key(2)))));}assertEquals(400,h.json("POST",ROOT,assess(),auth("admin")).statusCode(),"scenario "+scenario);}
  seed();MigrationSource.status=403;var failed=h.json("POST",ROOT,assess(),auth("admin"));assertEquals(502,failed.statusCode());assertFalse(html(failed).contains(MigrationSource.TOKEN));MigrationSource.status=200;MigrationSource.raw="not-json";assertEquals(502,h.json("POST",ROOT,assess(),auth("admin")).statusCode());MigrationSource.reset();
 }
 static void changesAndConcurrency(WorkflowSupport h)throws Exception{
  seed();String id=create(h);review(h,id);Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");var changed=new LinkedHashMap<>(original);changed.put("label","Revised incident label");db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(changed));db.connection.commit();}assertEquals(false,page(h,id).get("current"));assertEquals(409,h.json("POST",ROOT+"/"+id,confirm(2),auth("admin")).statusCode());review(h,id);try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}assertEquals(409,h.json("POST",ROOT+"/"+id,confirm(3),auth("admin")).statusCode());review(h,id);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var first=pool.submit(()->result(h.json("POST",ROOT+"/"+id,confirm(4),auth("admin")),200).get("job_id"));var second=pool.submit(()->result(h.json("POST",ROOT+"/"+id,confirm(4),auth("admin")),200).get("job_id"));assertEquals(first.get(),second.get());}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_transfer_job"));}
  for(String operation:List.of("read","create")){var changed=new LinkedHashMap<>(original);changed.put("record_roles",map(operation,List.of("agent")));try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(changed));db.connection.commit();}assertEquals(403,h.json("POST",ROOT,assess(),auth("admin")).statusCode());var directory=result(h.get(ROOT,auth("admin")),200);assertFalse(objects(directory.get("targets")).stream().anyMatch(row->row.get("name").equals("incident")));}try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name='incident'",JSON.writeValueAsString(original));db.connection.commit();}
 }
 static void limits(WorkflowSupport h)throws Exception{
  seed();String id=create(h);try(var db=h.store.open()){var source=db.one("SELECT * FROM os_source_assessment WHERE assessment_id=?",id);for(int n=1;n<20;n++)db.update("INSERT INTO os_source_assessment(assessment_id,owner_id,source_url,source_table,target,definition,revision,job_id,created) VALUES(?,?,?,?,?,?,1,'',?)",Values.id(),source.get("owner_id"),source.get("source_url"),"incident","incident",JSON.writeValueAsString(source.get("definition")),now());db.connection.commit();}int before=MigrationSource.queries.size();assertEquals(400,h.json("POST",ROOT,assess(),auth("admin")).statusCode());assertEquals(before,MigrationSource.queries.size());h.account("MappingCapacity","admin");try(var db=h.store.open()){String owner=RecordAccess.owner(db,"MappingCapacity");var source=db.one("SELECT * FROM os_source_assessment WHERE assessment_id=?",id);for(int n=20;n<5000;n++)db.update("INSERT INTO os_source_assessment(assessment_id,owner_id,source_url,source_table,target,definition,revision,job_id,created) VALUES(?,?,?,?,?,?,1,'',?)",Values.id(),owner,source.get("source_url"),"incident","incident",JSON.writeValueAsString(source.get("definition")),now());db.update("DELETE FROM os_source_assessment WHERE owner_id=? AND assessment_id<>?",RecordAccess.owner(db,"admin"),id);for(int n=0;n<19;n++)db.update("INSERT INTO os_source_assessment(assessment_id,owner_id,source_url,source_table,target,definition,revision,job_id,created) VALUES(?,?,?,?,?,?,1,'',?)",Values.id(),owner,source.get("source_url"),"incident","incident",JSON.writeValueAsString(source.get("definition")),now());db.connection.commit();}assertEquals(400,h.json("POST",ROOT,assess(),auth("admin")).statusCode());assertEquals(before,MigrationSource.queries.size());
 }
}
